#!/usr/bin/env python3
"""Original MIT SH-2 high-resolution rotation diagnostics; adjacent LICENSE.

1997 VDP2 §§2.1/6.1/6.3/6.4/8.1. Word100=TVMD,102=source seed,
104=horizontal translation/table start,106=BGON,108=RBG0 A/B selection.
Every image, name, palette, matrix, coefficient and record is guest-created.
"""
import argparse
import hashlib
from pathlib import Path
from build_clock import put8, put16, read
from build_scu import store
from build_hle_system import record
from build_video_transactions import encode, blank

HERE = Path(__file__).resolve().parent


def build():
    files = {}
    for mode in ['tile', 'bitmap', 'rbg1', 'coefficient']:
        dual = mode == 'rbg1'
        bitmap = mode in ['bitmap', 'coefficient']
        coefficient = mode == 'coefficient'
        image = 0x25e40000 if dual else 0x25e20000
        s = '; Original MIT high-resolution rotation picture diagnostic.\n'
        # SMPC DOTSEL must match graphic A/B. Select the PLL before setup:
        # a clock command resets video state, including TVMD and VRAM.
        s += (put8(0x20100063, 1) + 'load 0x100,r1\nmov.w @r1,r0\ntst #1,r0\n'
              'bt slow_clock\nmov #14,r0\nbra clock_command\nnop\n'
              'slow_clock:\nmov #15,r0\nclock_command:\nload 0x2010001f,r1\nmov.b r0,@r1\n'
              'load 0x20100063,r1\nclock_wait:\nmov.b @r1,r0\ntst #1,r0\nbf clock_wait\n')
        for base in [0x25e70000, 0x25e70080]:
            for off, value in [(0x14,0 if coefficient else 0x10000),(0x1c,0x10000),
                               (0x2c,0x10000),(0x4c,0x10000),(0x50,0x10000),
                               (0x5c,0x10000 if coefficient else 0)]:
                s += store(base+off,value)
            s += 'load 0x104,r1\nmov.w @r1,r0\nshll8 r0\nshll8 r0\n'
            s += f'load {base+(0x54 if coefficient else 0x44):#x},r1\nmov.l r0,@r1\n'
        for at,value in [(0xe,0x30e if dual else 0x11d if coefficient else 0x10e),
                         (0x28,0x20),(0x2a,0x3200 if bitmap else 0x2000),
                         (0x3e,0x10 if dual else 0x11 if bitmap else 0),
                         (0x38,0),(0x30,0),(0x60,0x1818 if dual else 0),
                         (0xfc,2),(0xf8,3),(0xbc,3),(0xbe,0x8000),
                         (0xb4,0xd0d if coefficient else 0),(0xb6,0x101 if coefficient else 0)]:
            s += put16(0x25f80000+at,value)
        if not bitmap:
            # 64 adjacent 8-dot cells; two-word names; legal A0/B1 pairing.
            s += f'load {0x25e60000 if dual else 0x25e00000:#x},r3\n'
            s += f'load {0x2000 if dual else 0x1000:#x},r4\nmov #64,r2\n'
            s += ('names:\nmov #0,r0\nmov.w r0,@r3\nadd #2,r3\nmov.w r4,@r3\n'
                  'add #2,r3\nadd #4,r4\ndt r2\nbf names\n')
        # Palette entries are generated by guest arithmetic, never host pixels.
        s += ('load 0x25f00000,r3\nload 0x8000,r4\nload 1024,r2\n'
              'palette:\nmov.w r4,@r3\nadd #2,r3\nadd #1,r4\ndt r2\nbf palette\n')
        s += (f'load {image:#x},r3\nload 0x102,r1\nmov.w @r1,r6\n'
              f'load {0x8000 if bitmap else 0:#x},r7\nmov #0,r2\nmov #0,r9\nload 512,r5\n')
        s += ('pixels:\nmov r2,r0\nadd r6,r0\nor r7,r0\nmov.w r0,@r3\n'
              'add r0,r9\nadd #2,r3\nadd #1,r2\n')
        if not bitmap:
            s += 'mov r2,r0\ntst #7,r0\nbf same_cell\nadd #112,r3\nsame_cell:\n'
        s += 'cmp/eq r5,r2\nbf pixels\n'
        if coefficient:
            # Long Xp entries in signed Q16.8: Xp[i]=i. Separate B port.
            s += ('load 0x25e40000,r3\nload 512,r2\nmov #0,r4\n'
                  'coefficients:\nmov r4,r0\nshll8 r0\nmov.l r0,@r3\n'
                  'add #4,r3\nadd #1,r4\ndt r2\nbf coefficients\n')
        s += ('load 0x108,r1\nmov.w @r1,r0\nload 0x25f800b0,r1\nmov.w r0,@r1\n'
              'load 0x106,r1\nmov.w @r1,r0\nload 0x25f80020,r1\nmov.w r0,@r1\n'
              'load 0x100,r1\nmov.w @r1,r0\nload 0x25f80000,r1\nmov.w r0,@r1\n')
        s += 'load 0x2600de00,r8\nmov r9,r0\n' + record()
        s += read(image,2) + read(image + (511*2 if bitmap else 63*128+14),2)
        # Read back the actual programmed translation/KAst, not a literal result.
        s += read(0x25e70080+(0x54 if coefficient else 0x44))
        s += read(0x25f80000,2) + read(0x25f80020,2) + read(0x25e7005c)
        s += blank('complete') + 'load 0x600d,r0\n' + record() + 'park:\nsleep\nbra park\nnop\n'
        outputs,digest = encode('rotation-hi-'+mode,s,[(0x100,0x8002),(0x102,1),(0x104,0),(0x106,0x30 if dual else 0x10),(0x108,0)])
        files.update(outputs)
        files['rotation-hi-'+mode+'.sha256'] = (digest+'\n').encode()
        values=[512*(0x8000 if bitmap else 0)+131328, (0x8000 if bitmap else 0)+1,
                (0x8000 if bitmap else 0)+512,0,0x8002,0x30 if dual else 0x10,
                0x10000 if coefficient else 0,0x600d]
        files['rotation-hi-'+mode+'.tsv'] = ''.join(f'{v:08X}\n' for v in values).encode()
    return files


if __name__ == '__main__':
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
    for name,data in build().items():
        path=HERE/name
        if args.check: assert path.read_bytes()==data,f'Rebuild {name}'
        else: path.write_bytes(data)
        print(f'{"Verified" if args.check else "Built"} {name}; SHA-256 {hashlib.sha256(data).hexdigest()}')
